// Astra — Recursive Fibonacci
// Demonstrates: functions, recursion, if/else, arithmetic, string concat, .to_string()

fn fib(n: int) -> int:
    if n <= 1:
        return n
    return fib(n - 1) + fib(n - 2)

fn main() -> int:
    print("Fibonacci sequence:")

    for i in 0..10:
        let result = fib(i)
        let msg = "  fib(" + i.to_string() + ") = " + result.to_string()
        print(msg)

    let answer = fib(10)
    print("fib(10) = " + answer.to_string())
    return 0

// Astra — Generic Functions
// Demonstrates: generics, type inference, monomorphization

fn identity<T>(value: T) -> T:
    return value

fn first<A, B>(a: A, b: B) -> A:
    return a

fn main() -> int:
    // Type inference: T = int
    let x = identity(42)
    print("identity(42) = " + x.to_string())

    // Type inference: T = str
    let s = identity("hello")

    // Multiple type parameters: A = int, B = str
    let result = first(100, "ignored")
    print("first(100, ignored) = " + result.to_string())

    return 0

// Astra — Structs
// Demonstrates: struct definition, creation, field access

struct Point:
    x: int
    y: int

fn distance_squared(p: int, q: int) -> int:
    return p * p + q * q

fn main() -> int:
    let origin = Point { x: 0, y: 0 }
    let target = Point { x: 3, y: 4 }

    let dx = target.x - origin.x
    let dy = target.y - origin.y
    let dist_sq = distance_squared(dx, dy)

    print("Point: (" + target.x.to_string() + ", " + target.y.to_string() + ")")
    print("Distance squared from origin: " + dist_sq.to_string())

    return 0

// Astra — Enums and Pattern Matching
// Demonstrates: a user-defined enum with a data variant and a unit variant,
// enum-typed return values, match expressions, payload extraction

enum Division:
    Quotient(int)
    DivByZero

fn divide(a: int, b: int) -> Division:
    if b == 0:
        return Division::DivByZero
    return Quotient(a / b)

fn describe(d: Division) -> int:
    return match d:
        Quotient(q) => q
        Division::DivByZero => -1

fn main() -> int:
    let value1 = describe(divide(10, 2))
    print("10 / 2 = " + value1.to_string())

    let value2 = describe(divide(10, 0))
    print("10 / 0 = " + value2.to_string() + " (division by zero)")

    return 0

// Astra — Strings and Text
// Demonstrates: `${}` interpolation, string methods, `split`, `parse_int`,
// functions that return strings, a list of strings built with `push`, and
// (v0.13.1) `for c in s`, `char_at`, `starts_with`, `replace` and `<` on strings.
// Every string is reference counted and freed when its last owner goes away.

fn initials(first: str, last: str) -> str:
    return first.substring(0, 1) + last.substring(0, 1)

fn grade(score: int) -> str:
    if score >= 90:
        return "A"
    if score >= 75:
        return "B"
    return "C"

fn describe(name: str, score: int) -> str:
    return "${name}: ${score} (${grade(score)})"

fn main() -> int:
    let csv = "Ada Lovelace,95;Alan Turing,88;Grace Hopper,72;Nobody,n/a"
    let rows = csv.split(";")
    print("${rows.length()} rows")

    let report: [str] = []
    let total = 0
    for row in rows:
        let fields = row.split(",")
        match parse_int(fields[1]):
            Some(score) =>
                let names = fields[0].split(" ")
                report.push(initials(names[0], names[1]) + "  " + describe(fields[0], score))
                total += score
            None => print("skipped: ${fields[0]} has no score")
    for line in report:
        print(line)
    print("average ${total / report.length()}")

    let title = "  astra text tools  "
    print("[" + title.trim().to_upper() + "]")
    print("mentions Hopper: ${csv.contains("Hopper")}")

    let word = "Mississippi"
    let s_count = 0
    for c in word:
        if c == "s":
            s_count += 1
    print("${word} has ${s_count} s's and starts with ${word.char_at(0)}")
    print("starts with Miss: ${word.starts_with("Miss")}")
    print(word.replace("ss", "SS"))
    print("Ada before Alan: ${"Ada" < "Alan"}")
    return 0

# 13_tuples_and_stats.astra — returning several values at once
#
# A function returns a tuple; the caller takes it apart with `let (a, b) = ...`
# or reads one element with `.0`, `.1`. No out-parameters, no wrapper struct.

fn stats(xs: [int]) -> (int, int, int):
    let lowest = xs[0]
    let highest = xs[0]
    let total = 0
    for x in xs:
        if x < lowest:
            lowest = x
        if x > highest:
            highest = x
        total += x
    return (lowest, highest, total)

fn divmod(a: int, b: int) -> (int, int):
    return (a / b, a % b)

fn main() -> int:
    let temperatures = [21, 19, 25, 30, 18, 24]
    let (lowest, highest, total) = stats(temperatures)
    print("min ${lowest}, max ${highest}, mean ${total / temperatures.length()}")

    let (minutes, seconds) = divmod(437, 60)
    print("437 seconds = ${minutes} min ${seconds} s")

    let corner = (3, 4)
    print("corner at x=${corner.0}, y=${corner.1}")
    return 0

# 14_validating_input.astra — parsing records with Result and `?`
#
# Each step that can fail returns Result<T, str>. `?` hands an error straight
# back to the caller, so the happy path reads top to bottom. The caller
# decides what to do with each error; nothing is thrown past it.

struct Person:
    name: str
    age: int

fn check_range(n: int) -> Result<int, str>:
    if n < 0 || n > 150:
        return Result::Err("${n} is not a plausible age")
    return Result::Ok(n)

fn parse_age(text: str) -> Result<int, str>:
    match parse_int(text.trim()):
        Some(n) => return check_range(n)
        None => return Result::Err("'${text.trim()}' is not a number")

# Checks a "name,age" line and returns the age.
fn validate(line: str) -> Result<int, str>:
    let fields = line.split(",")
    if fields.length() != 2:
        return Result::Err("expected name,age in '${line}'")
    if fields[0].trim().length() == 0:
        return Result::Err("the name is empty in '${line}'")
    let age = parse_age(fields[1])?
    return Result::Ok(age)

fn main() -> int:
    let lines = ["Ada, 36", "Alan,41", "Grace,abc", "Linus,-3", ",20", "no comma here"]
    let people: [Person] = []
    for line in lines:
        match validate(line):
            Result::Ok(age) =>
                let p = Person { name: line.split(",")[0].trim(), age: age }
                people.push(p)
                print("ok     ${p.name}, ${p.age}")
            Result::Err(e) => print("error  ${e}")
    print("${people.length()} of ${lines.length()} records are valid")
    return 0

# 16_algorithms.astra — classic algorithms on lists
#
# Sorting in place through a `mut` parameter, binary search returning an
# Option, a prime sieve, and Euclid's gcd. Every index is bounds-checked and
# every integer operation checked for overflow, and the native build runs
# at the speed of overflow-checked Rust.

fn insertion_sort(mut xs: [int]):
    let i = 1
    while i < xs.length():
        let key = xs[i]
        let j = i - 1
        while j >= 0 && xs[j] > key:
            xs[j + 1] = xs[j]
            j -= 1
        xs[j + 1] = key
        i += 1

fn binary_search(xs: [int], target: int) -> Option<int>:
    let lo = 0
    let hi = xs.length() - 1
    while lo <= hi:
        let mid = (lo + hi) / 2
        if xs[mid] == target:
            return Some(mid)
        if xs[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return None

fn count_primes(limit: int) -> int:
    let composite: [bool] = []
    for i in 0..limit + 1:
        composite.push(false)
    let count = 0
    for n in 2..limit + 1:
        if !composite[n]:
            count += 1
            let m = n * n
            while m <= limit:
                composite[m] = true
                m += n
    return count

fn gcd(a: int, b: int) -> int:
    if b == 0:
        return a
    return gcd(b, a % b)

fn show(xs: [int]) -> str:
    let text = ""
    for x in xs:
        text = text + "${x} "
    return text.trim()

fn main() -> int:
    let xs = [38, 7, 91, 15, 2, 64, 23]
    insertion_sort(mut xs)
    print("sorted: ${show(xs)}")

    match binary_search(xs, 64):
        Some(i) => print("64 is at index ${i}")
        None => print("64 not found")
    match binary_search(xs, 50):
        Some(i) => print("50 is at index ${i}")
        None => print("50 not found")

    print("primes up to 100000: ${count_primes(100000)}")
    print("gcd(1071, 462) = ${gcd(1071, 462)}")
    return 0

# 17_bank_accounts.astra — a small domain model
#
# Money is kept in whole cents (int), so there is no rounding. A function
# changes an account only when it takes it as `mut` and the caller says `mut`
# too, so every place that can move money is visible at the call. Rule
# violations come back as Result errors.

struct Account:
    owner: str
    cents: int

fn money(cents: int) -> str:
    let rest = cents % 100
    let pad = rest < 10 ? "0" : ""
    return "$${cents / 100}.${pad}${rest}"

fn deposit(mut a: Account, cents: int) -> Result<int, str>:
    if cents <= 0:
        return Result::Err("a deposit must be positive")
    a.cents += cents
    return Result::Ok(a.cents)

fn withdraw(mut a: Account, cents: int) -> Result<int, str>:
    if cents > a.cents:
        return Result::Err("${a.owner} has ${money(a.cents)}, can't take ${money(cents)}")
    a.cents -= cents
    return Result::Ok(a.cents)

fn transfer(mut from: Account, mut to: Account, cents: int) -> Result<int, str>:
    let left = withdraw(mut from, cents)?
    deposit(mut to, cents)?
    return Result::Ok(left)

fn report(a: Account):
    print("  ${a.owner}: ${money(a.cents)}")

fn main() -> int:
    let alice = Account { owner: "Alice", cents: 120000 }
    let bob = Account { owner: "Bob", cents: 5050 }

    match transfer(mut alice, mut bob, 25005):
        Result::Ok(left) => print("sent $250.05; Alice has ${money(left)} left")
        Result::Err(e) => print("failed: ${e}")

    match transfer(mut bob, mut alice, 1000000):
        Result::Ok(left) => print("sent $10000.00")
        Result::Err(e) => print("failed: ${e}")

    match deposit(mut bob, -5):
        Result::Ok(total) => print("deposited")
        Result::Err(e) => print("failed: ${e}")

    print("balances:")
    report(alice)
    report(bob)
    return 0

# 18_rpn_calculator.astra — tokenize and evaluate an expression
#
# Reverse Polish notation: "3 4 + 2 *" means (3 + 4) * 2. The text is split
# into tokens, numbers go on a stack, operators take two values off it. Bad
# input (an unknown token, too few values, division by zero) is an error
# value with a clear message.

fn apply(op: str, a: int, b: int) -> Result<int, str>:
    if op == "+":
        return Result::Ok(a + b)
    if op == "-":
        return Result::Ok(a - b)
    if op == "*":
        return Result::Ok(a * b)
    if op == "/":
        if b == 0:
            return Result::Err("division by zero")
        return Result::Ok(a / b)
    return Result::Err("unknown token '${op}'")

fn evaluate(expr: str) -> Result<int, str>:
    let stack: [int] = []
    let size = 0
    for token in expr.split(" "):
        match parse_int(token):
            Some(n) =>
                if size < stack.length():
                    stack[size] = n
                else:
                    stack.push(n)
                size += 1
            None =>
                if size < 2:
                    return Result::Err("'${token}' needs two values before it")
                let b = stack[size - 1]
                let a = stack[size - 2]
                stack[size - 2] = apply(token, a, b)?
                size -= 1
    if size != 1:
        return Result::Err("${size} values left over")
    return Result::Ok(stack[0])

fn main() -> int:
    let inputs = ["3 4 + 2 *", "100 7 - 3 /", "1 2 3 4 + + +", "5 0 /", "2 +", "6 2 ^", "1 2"]
    for expr in inputs:
        match evaluate(expr):
            Result::Ok(v) => print("${expr}  =  ${v}")
            Result::Err(e) => print("${expr}  :  error, ${e}")
    return 0

# 23_elif_defaults_sqrt.astra — elif, default arguments and sqrt
#
# `elif` chains conditions in the indented syntax. A parameter can have a
# default value (a literal; defaults come last), so a call may leave it off.
# `sqrt` takes an int or a float and returns a float.

struct Point:
    x: float
    y: float

fn distance(a: Point, b: Point) -> float:
    let dx = a.x - b.x
    let dy = a.y - b.y
    return sqrt(dx * dx + dy * dy)

fn band(km: float, near: float = 2.0, far: float = 10.0) -> str:
    if km <= near:
        return "walk"
    elif km <= far:
        return "cycle"
    else:
        return "drive"

fn label(name: str, km: float, unit: str = "km") -> str:
    return "${name}: ${km} ${unit}"

fn main() -> int:
    let home = Point { x: 0.0, y: 0.0 }
    let shops = [Point { x: 1.0, y: 1.0 }, Point { x: 6.0, y: 8.0 }, Point { x: 9.0, y: 12.0 }]
    let names = ["bakery", "market", "station"]
    for i in 0..shops.length():
        let km = distance(home, shops[i])
        print("${label(names[i], km)} -> ${band(km)}")
    print("strict: ${band(5.0, 1.0, 4.0)}")
    print("side of a 49 m2 square: ${sqrt(49)} m")
    return 0
